この SpanTree コンポーネント、レビューして。属性の取り出しと失敗判定が render の中にあるのと、isError みたいな boolean props が増えてきてる。どう直すべき？

```tsx
export const SpanNodeView = ({ node, compact }: { node: SpanNode; compact?: boolean }) => {
  const isError = node.status.code === 2;
  const model = typeof node.attributes["mg.llm.model"] === "string" ? node.attributes["mg.llm.model"] : undefined;
  const tokens = JSON.parse(String(node.attributes["mg.llm.usage"] ?? "{}"));
  return (
    <div className={isError ? "span span-error" : compact ? "span span-compact" : "span"} style={{ borderColor: isError ? "#d33" : undefined }}>
      ...
    </div>
  );
};
